from transforms3d.euler import quat2euler

# Transform matrix function
def transform_matrix(points):
    # Dönüşüm matrisi oluşturma (2D dönüşüm)
    R = np.array([
        [np.cos(yaw), -np.sin(yaw)],
        [np.sin(yaw), np.cos(yaw)]
    ])

    # Noktaların global konumunu hesaplama
    global_points = np.dot(points, R.T) + current_pose

    return global_points

def pose_callback(data):
    # print("pose")
    global current_pose
    global yaw  #rad
    # print(data)
    _, _, yaw = quat2euler(
        [data.pose.pose.orientation.w,
        data.pose.pose.orientation.x,
        data.pose.pose.orientation.y,
        data.pose.pose.orientation.z])
    current_pose = np.array([data.pose.pose.position.x, data.pose.pose.position.y])
    # print("yaw:", yaw)

